Here is the commit message:
dmaengine: dw: dmamux: fix OF node leak on route allocation
 failure

Make sure to drop the reference taken to the DMA master OF node also on
late route allocation failures.

Fixes: 134d9c52fca2 ("dmaengine: dw: dmamux: Introduce RZN1 DMA router support")
Cc: stable@vger.kernel.org	# 5.19
Cc: Miquel Raynal <miquel.raynal@bootlin.com>
Signed-off-by: Johan Hovold <johan@kernel.org>
Reviewed-by: Miquel Raynal <miquel.raynal@bootlin.com>
Link: https://patch.msgid.link/20251117161258.10679-6-johan@kernel.org
Signed-off-by: Vinod Koul <vkoul@kernel.org>

Here is the root cause:
when the requested channel is already in use (`test_and_set_bit` fails) and after clearing the bitmap when later operations fail. This leads to an OF node reference leak.

Here is the patch:

 static void *rzn1_dmamux_route_allocate(struct of_phandle_args *dma_spec,
 					struct of_dma *ofdma)
 {
 	struct platform_device *pdev = of_find_device_by_node(ofdma->of_node);
 	struct rzn1_dmamux_data *dmamux = platform_get_drvdata(pdev);
 	struct rzn1_dmamux_map *map;
 	unsigned int dmac_idx, chan, val;
 	u32 mask;
 	int ret;

 	if (dma_spec->args_count != RNZ1_DMAMUX_NCELLS) {
 		ret = -EINVAL;
 		goto put_device;
 	}

 	map = kzalloc(sizeof(*map), GFP_KERNEL);
 	if (!map) {
 		ret = -ENOMEM;
 		goto put_device;
 	}

 	chan = dma_spec->args[0];
 	map->req_idx = dma_spec->args[4];
 	val = dma_spec->args[5];
 	dma_spec->args_count -= 2;

 	if (chan >= RZN1_DMAMUX_LINES_PER_CTLR) {
 		dev_err(&pdev->dev, "Invalid DMA request line: %u\n", chan);
 		ret = -EINVAL;
 		goto free_map;
 	}

 	if (map->req_idx >= RZN1_DMAMUX_MAX_LINES ||
 	    (map->req_idx % RZN1_DMAMUX_LINES_PER_CTLR) != chan) {
 		dev_err(&pdev->dev, "Invalid MUX request line: %u\n", map->req_idx);
 		ret = -EINVAL;
 		goto free_map;
 	}

 	dmac_idx = map->req_idx >= RZN1_DMAMUX_LINES_PER_CTLR ? 1 : 0;
 	dma_spec->np = of_parse_phandle(ofdma->of_node, "dma-masters", dmac_idx);
 	if (!dma_spec->np) {
 		dev_err(&pdev->dev, "Can't get DMA master\n");
 		ret = -EINVAL;
 		goto free_map;
 	}

 	dev_dbg(&pdev->dev, "Mapping DMAMUX request %u to DMAC%u request %u\n",
 		map->req_idx, dmac_idx, chan);

 	if (test_and_set_bit(map->req_idx, dmamux->used_chans)) {
 		ret = -EBUSY;
-		goto free_map;
+		goto put_dma_spec_np;
 	}

 	mask = BIT(map->req_idx);
 	ret = r9a06g032_sysctrl_set_dmamux(mask, val ? mask : 0);
 	if (ret)
 		goto clear_bitmap;

 	put_device(&pdev->dev);
 	return map;

 clear_bitmap:
 	clear_bit(map->req_idx, dmamux->used_chans);
+put_dma_spec_np:
+	of_node_put(dma_spec->np);
 free_map:
 	kfree(map);
 put_device:
 	put_device(&pdev->dev);

 	return ERR_PTR(ret);
 }



